import { BaseEvent } from '@common/events';

import { OrderEventTypes } from './order-event-types';

export interface CreateOrderRequestedPayload {
  /**
   * Generated by the gateway so the request is idempotent and the client
   * gets the id immediately. Optional only for messages published before
   * this field existed.
   */
  orderId?: string;
  userId: string;
  /** Integer amount in cents (e.g. 1999 = 19.99), never a float */
  totalCents: number;
}

export class CreateOrderRequestedEvent extends BaseEvent<
  CreateOrderRequestedPayload,
  OrderEventTypes
> {
  readonly eventType = OrderEventTypes.ORDER_CREATE_REQUESTED;
}
